import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-D1qvD-xD.js";var i=JSON.parse(`{"path":"/vm/esxi/8iu5gpv8/","title":"ESXi 直通 SATA 控制器 | ESXi","lang":"zh-CN","frontmatter":{"title":"ESXi 直通 SATA 控制器","createTime":"2026/08/26 14:54:27","permalink":"/vm/esxi/8iu5gpv8/"},"readingTime":{"minutes":2.93,"words":878},"git":{},"filePathRelative":"vm/esxi/002.passthrough-sata-controller.md","headers":[]}`),a={name:`002.passthrough-sata-controller.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>把物理存储设备交给 ESXi 上的虚拟机独占使用，常见有两种层次的方案：</p><ul><li><strong>PCI 设备直通（DirectPath I/O）</strong>：把整块 SATA/NVMe 控制器直接分配给虚拟机，绕过 hypervisor 的磁盘抽象层，性能最好，适合跑 ZFS、软 RAID 等需要直接管理磁盘的场景。</li><li><strong>RDM（Raw Device Mapping，原始设备映射）</strong>：不碰控制器，只把单块物理硬盘以映射盘的形式挂给虚拟机，控制更精细，但虚拟机看到的是一块「磁盘」而非真实控制器。</li></ul><p>下文分别记录两种方案的配置过程，最后给出选型对比。</p><h2 id="一、pci-设备直通-sata-控制器" tabindex="-1"><a class="header-anchor" href="#一、pci-设备直通-sata-控制器"><span>一、PCI 设备直通（SATA 控制器）</span></a></h2><h3 id="_1-识别目标设备" tabindex="-1"><a class="header-anchor" href="#_1-识别目标设备"><span>1. 识别目标设备</span></a></h3><p>先确认主机上的 SATA 控制器及其 PCI ID：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Class 0106&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><p>输出示例：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">0000:00:17.0 Mass storage controller SATA controller: Intel Corporation Comet Lake SATA AHCI Controller</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         Class 0106: 8086:06d2</span></span></code></pre></div><p><code>Class 0106</code> 即 SATA 存储控制器类代码，本例中厂商/设备 ID 为 <code>8086:06d2</code>。</p><h3 id="_2-编辑-passthru-map" tabindex="-1"><a class="header-anchor" href="#_2-编辑-passthru-map"><span>2. 编辑 passthru.map</span></a></h3><p>ESXi 通过 <code>/etc/vmware/passthru.map</code> 维护 PCI 设备直通名单，按 <code>厂商ID 设备ID 复位方式 是否可共享</code> 的格式逐行登记：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/vmware/passthru.map</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 追加一行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">8086</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   06d2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    d3d0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    false</span></span></code></pre></div><p>各字段含义（文件头自带注释：<code>file format: vendor-id device-id resetMethod fptShareable</code>）：</p><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>厂商ID  设备ID  复位方式      是否可共享(fptShareable)</span></span></code></pre></div><ul><li><code>8086</code>：Intel 厂商 ID（Vendor ID），<code>ffff</code> 可作通配</li><li><code>06d2</code>：设备 ID（Device ID），<code>ffff</code> 可作通配</li><li><code>d3d0</code>：复位方式（resetMethod），直通设备释放回 ESXi 时采用的复位手段，取值为 <code>flr</code> / <code>d3d0</code> / <code>link</code> / <code>bridge</code> / <code>default</code>；<code>d3d0</code> 即 D3 电源态复位，是 SATA 控制器最常见的选项</li><li><code>false</code>：是否可共享（fptShareable）。<code>true</code>/<code>default</code> 表示该设备可被共享直通，<code>false</code> 表示独占、只能分配给一台虚拟机；SATA 控制器通常设为 <code>false</code></li></ul><h3 id="_3-验证与启用" tabindex="-1"><a class="header-anchor" href="#_3-验证与启用"><span>3. 验证与启用</span></a></h3><p>重启前可在 ESXi Shell 中确认设备是否进入直通就绪状态：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmkchdev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 06d2</span></span></code></pre></div><p>对目标设备启用直通（修改 passthru.map 后需执行）：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmkchdev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0000:00:17.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span></span></code></pre></div><p>完成后重启 ESXi，在虚拟机设置的「添加 PCI 设备」中选择该控制器即可。</p><div class="hint-container warning"><p class="hint-container-title">警告</p><ol><li>控制器被直通后，其下挂载的所有物理硬盘将不再被 ESXi 识别，只能由对应虚拟机独占访问。</li><li>部分主板 SATA 控制器不具备独立 IOMMU 分组，会导致直通失败或连带影响其他设备。</li><li>直通生效依赖硬件支持 ACS/IOMMU，操作前建议在 BIOS 中确认 VT-d 已开启。</li></ol></div><h2 id="二、rdm-原始设备映射" tabindex="-1"><a class="header-anchor" href="#二、rdm-原始设备映射"><span>二、RDM 原始设备映射</span></a></h2><p>RDM 不直通控制器，而是在 ESXi 层为某块物理硬盘创建一枚指向它的 <code>.vmdk</code> 映射文件，虚拟机通过这块映射盘访问真实磁盘。建立映射使用 <code>vmkfstools -z</code>：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmkfstools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -z</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /vmfs/devices/disks/t10.ATA_____Disk123456</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /vmfs/volumes/datastore1/vmname/disk1.vmdk</span></span></code></pre></div><p>映射盘创建后，将其作为现有硬盘添加到虚拟机即可，底层磁盘路径保持不变。</p><h2 id="三、方案选型" tabindex="-1"><a class="header-anchor" href="#三、方案选型"><span>三、方案选型</span></a></h2><table><thead><tr><th>方案</th><th>用途</th><th>适用场景</th></tr></thead><tbody><tr><td>PCI 直通（DirectPath I/O）</td><td>直通整个 SATA/NVMe 控制器</td><td>高性能、ZFS、软 RAID 场景</td></tr><tr><td>RDM（原始设备映射）</td><td>直通单块物理硬盘</td><td>精细控制单块磁盘映射</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>要给虚拟机整块控制器、追求性能、需要虚拟机直接管理磁盘（如 ZFS、软 RAID），选 PCI 直通；只想把某一两块盘单独交给虚拟机、又不想动控制器，选 RDM。</p></div>`,31)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};